"""Append executed development replay without rerunning or replacing pilot cells."""
from pathlib import Path
import json
import os
import nbformat as n
from nbclient import NotebookClient

ROOT=Path(__file__).resolve().parents[1]
PATH=ROOT/'notebooks/06_efficientad.ipynb'
OUT=ROOT/'reports/efficientad/development'


def main():
    nb=n.read(PATH,4)
    if nb.metadata.get('efficientad_development_replay'):
        raise RuntimeError('Development already appended; inspect existing notebook before updating')
    gate=json.loads((OUT/'feasibility.json').read_text())
    selection=json.loads((OUT/'selection.json').read_text())
    latency=json.loads((OUT/'latency.json').read_text())
    results=[json.loads(p.read_text()) for p in sorted(OUT.glob('06-dev-*-v1.json'))]
    selected=selection['selected']
    cells=[]
    def md(text): cells.append(n.v4.new_markdown_cell(text))
    def code(text): cells.append(n.v4.new_code_cell(text))
    md('### Development continuation — bounded study\n\nThe preceding 20 sections preserve the original pilot record and saved outputs. The following continuation supersedes its pending-development statements. It replays four newly executed fits and diagnostics; it does not launch training or final evaluation. The predeclared plan, fidelity audit and all successful or failed events are retained in the repository.')
    code("from pathlib import Path\nimport json, sys\nimport pandas as pd\nimport numpy as np\nimport matplotlib.pyplot as plt\nROOT = Path.cwd() if (Path.cwd()/'reports').exists() else Path.cwd().parent\nassert Path(sys.executable).resolve() == ROOT/'.venv/Scripts/python.exe'\nD = ROOT/'reports/efficientad/development'\nplan = json.loads((ROOT/'configs/efficientad_development.json').read_text())\nresults = [json.loads(p.read_text()) for p in sorted(D.glob('06-dev-*-v1.json'))]\nselection = json.loads((D/'selection.json').read_text())\ngate = json.loads((D/'feasibility.json').read_text())\nlatency = json.loads((D/'latency.json').read_text())\nprint({'replay': True, 'fits': len(results), 'steps': sum(r['steps'] for r in results), 'plan': plan})")
    md('The plan was saved before training: bottle (147 fit normals) and carpet (196), fresh seed-2026 models at 3 and 9 epochs, 4,116 optimizer steps total. This supersedes the earlier proposed 12-fit study. Fixed epochs expose every fitting normal equally. No official test images, masks or scores were opened; test counts/dimensions come only from prior metadata for cost estimates.')
    md('### Reference fidelity and implementation\n\nRead the complete audit below. The architecture remains the padded PDN-S teacher/student and 64x1x1-bottleneck autoencoder. The reduced epoch budget, omitted external-image penalty, constant short-run learning rate and tensor photometric augmentation are disclosed differences from the paper. Missing external penalty may let the student imitate teacher features beyond normals; the effect on real anomalies has not been measured.')
    code("print((ROOT/'docs/efficientad_fidelity_audit.md').read_text(encoding='utf-8'))\nimport inspect\nimport importlib.util\nspec = importlib.util.spec_from_file_location('efficientad_development_driver', ROOT/'scripts/develop_efficientad.py')\ndriver = importlib.util.module_from_spec(spec)\nspec.loader.exec_module(driver)\nprint(inspect.getsource(driver.fit))")
    md('The training code explicitly exposes shuffle order, random augmentation, hard loss, joint AE objectives, finite-gradient checks and complete-epoch timing. Teacher moments use every fitting normal and are cached by teacher/manifest/core identity for the second budget. Every completed fit has a checkpoint, map quantiles, exact replay check, result JSON, CSV diagnostics and append-only registry result. No existing pilot architecture was reimplemented.')
    md('### Latency diagnosis\n\nUse the same saved pilot checkpoint for a controlled measurement audit: identical 1x3x256x256 FP32 input and unchanged model semantics. After 50 warmups per repeat, synchronize around 100 resident-input forwards in each of three repeats and record both wall and CUDA event time. Transfer and file-decode-through-CPU-map paths are timed separately. Events include stream launch gaps, so they are not a sum of isolated kernel durations.')
    code("print(json.dumps({k:v for k,v in latency.items() if k not in ('samples','end_to_end_samples_ms','transfer_samples_ms')}, indent=2))\nwall = np.array([r['wall_ms'] for r in latency['samples']])\nevents = np.array([r['gpu_ms'] for r in latency['samples']])\nplt.plot(wall, label='synchronized wall'); plt.plot(events, label='CUDA event', alpha=.7)\nplt.xlabel('Resident batch-one measurement'); plt.ylabel('ms'); plt.legend(); plt.show()")
    md(f"Resident wall p50/p95 = {latency['resident_wall']['p50_ms']:.2f}/{latency['resident_wall']['p95_ms']:.2f} ms, CUDA event = {latency['resident_gpu_event']['p50_ms']:.2f}/{latency['resident_gpu_event']['p95_ms']:.2f} ms (300 runs). End-to-end = {latency['end_to_end']['p50_ms']:.2f}/{latency['end_to_end']['p95_ms']:.2f} ms (100 runs); H2D = {latency['host_to_device']['p50_ms']:.3f}/{latency['host_to_device']['p95_ms']:.3f} ms. This run has a smaller p95 than the pilot, without a faster median. P0 and sampled clocks were stable; bursts did not remove the cost. CPU process usage near one core and modest GPU utilization are consistent with host/driver launch overhead. Windows scheduling remains a possible cause, not proven. No power/clock settings or score semantics were changed.")
    md('### Exploratory host-launch control, after selection\n\nThe initial audit motivates an execution-only CUDA graph control on the selected bottle checkpoint. It is run after the four fits and selection, and cannot influence model selection. Eager and graph execute the same full model, including both maps. Equality is checked before timing and on three additional normal inputs; capture failure is retained. Graph timing excludes capture and transfers and is not silently substituted into the final compute estimate.')
    code("control = json.loads((D/'launch-control.json').read_text())\nprint(json.dumps({k:v for k,v in control.items() if k not in ('eager','graph')},indent=2))\nprint({k:{m:v[m] for m in ('wall','gpu_event')} for k,v in control.items() if k in ('eager','graph')})")
    control=json.loads((OUT/'launch-control.json').read_text())
    if control['graph_status']=='measured':
        md(f"The paired eager wall p50/p95 is {control['eager']['wall']['p50_ms']:.2f}/{control['eager']['wall']['p95_ms']:.2f} ms; fixed-shape graph replay is {control['graph']['wall']['p50_ms']:.2f}/{control['graph']['wall']['p95_ms']:.2f} ms (300 each). Graph capture, image transfer and preprocessing are excluded. A lower graph time supports host-dispatch overhead as a contributor, without identifying a specific Windows scheduling mechanism. All subsequent feasibility arithmetic conservatively retains eager timing. This exploratory control changes execution scheduling, not architecture, weights or anomaly-score definitions.")
    else:
        md('CUDA graph control was unavailable; its recorded failure is retained rather than converted into an invented latency. Eager timings remain the basis for feasibility. Operator profiling and telemetry are descriptive and cannot isolate every source of Windows GPU scheduling variability.')
    md('### Full-epoch learning curves\n\nEvery plotted point below is a recorded full epoch. Training means include hard-feature, autoencoder and student-autoencoder loss; held-out normal maxima track unnormalized score drift without repeatedly refitting maps. A falling loss is necessary but does not establish anomaly sensitivity. Fixed fitting probes before/after also separate training-mode dropout fluctuations from actual learning.')
    code("fig, axes = plt.subplots(2, 3, figsize=(13,7))\nfor i, category in enumerate(plan['categories']):\n    for r in results:\n        if r['category'] != category: continue\n        curves = pd.DataFrame(r['curves'])\n        for j,key in enumerate(('hard','autoencoder','student_autoencoder')):\n            axes[i,j].plot(curves.epoch, curves[key], marker='.', label=f\"{r['epochs']} epochs\")\n            axes[i,j].set_title(category+' / '+key); axes[i,j].set_xlabel('Epoch'); axes[i,j].legend()\nfig.tight_layout(); plt.show()\nfig, axes = plt.subplots(1,2,figsize=(10,3))\nfor ax,category in zip(axes,plan['categories']):\n    for r in results:\n        if r['category'] != category: continue\n        curves = pd.DataFrame(r['curves'])\n        ax.plot(curves.epoch,curves.raw_local_dev_max_median,label=f\"local/{r['epochs']} epochs\")\n        ax.plot(curves.epoch,curves.raw_global_dev_max_median,linestyle='--',label=f\"global/{r['epochs']} epochs\")\n    ax.set_title(category+' fixed held-out normal subset'); ax.set_xlabel('Epoch'); ax.legend()\nfig.tight_layout(); plt.show()\nprint(pd.DataFrame([dict(category=r['category'],epochs=r['epochs'],steps=r['steps'],train_seconds=r['training_seconds'],hard_before=r['probe_before']['hard'],hard_after=r['probe_after']['hard'],ae_before=r['probe_before']['autoencoder'],ae_after=r['probe_after']['autoencoder'],development_probe=r['development_probe_losses']) for r in results]).to_string(index=False))")
    md('All meaningful epoch fluctuations are retained. Compare the fixed-probe endpoints and held-out development score drift with the synthetic discrimination table below. Different score scales across budgets are expected before development-map normalization; they do not by themselves imply worsening normal false alarms. This study has one development seed and cannot establish across-seed stability.')
    md('### Proxy discrimination and autoencoder contribution\n\nFor 16 fitting normals per category, deterministic scratch, block and color edits yield 48 synthetic anomalous images. Their backgrounds participated in fitting, so results are optimistic proxies rather than real-defect generalization. Report each edit and paired score change. Combined versus local-only is an inference map ablation with identical trained weights; global-only, raw-map and top-1%-mean are diagnostic scores, not extra selected trials.')
    code("rows = []\nfor r in results:\n    for score,v in r['proxy'].items():\n        rows.append(dict(category=r['category'],epochs=r['epochs'],score=score,proxy_auroc=v['auroc'],proxy_ap=v['ap'],scratch=v['per_edit']['scratch'],block=v['per_edit']['block'],color_patch=v['per_edit']['color_patch'],paired_delta=v['mean_paired_score_delta']))\nprint(pd.DataFrame(rows).to_string(index=False))\nprint('Development-normal score distributions and leave-one-image-out map-scaling ranges:')\nfor r in results:\n    print(r['experiment_id'], r['development_score_distributions'], r['leave_one_development_image_out_quantile_range'])\nprint('Across-budget normal score rank correlations:')\nfrom scipy.stats import spearmanr\nfor category in plan['categories']:\n    tables = [pd.read_csv(D/f\"06-dev-{category}-e{e}-seed2026-v1-development.csv\").set_index('path') for e in plan['epoch_budgets']]\n    print(category, {s: float(spearmanr(tables[0][s],tables[1].loc[tables[0].index,s]).statistic) for s in plan['candidate_scores']})")
    md('The sensitivity varies by edit and category; none of these scores is official-test AUROC. Proxy AP has a .75 random-ranking reference because 48 of 64 proxy-panel images are edited, and edits share only 16 backgrounds. Normal development distributions and leave-one-out map quantiles expose scaling instability without using reserved calibration for selection. Rejected score diagnostics remain in every CSV. Structural/logical anomalies and fine real scratches remain untested. See the selection table for the predeclared decision rather than choosing the best individual edit retrospectively.')
    md('### Configuration selection, locked before calibration\n\nEligibility requires finite losses/gradients/maps, lower fitting-probe hard and AE losses, and proxy AUROC at least .65 in each category. Rank macro proxy AUROC; select three epochs if within .02 of the best eligible nine-epoch candidate, and prefer combined-max within .02 of local-max. The selection JSON was written before opening reserved calibration images.')
    code("print(json.dumps(selection, indent=2))\nprint('Candidate decisions:')\nprint(pd.DataFrame(selection['candidates']).to_string(index=False))")
    md(f"Selected **{selected['epochs']} epochs, {selected['score']}**, eligibility={selection['eligible']}, macro proxy AUROC={selected['macro_proxy_auroc']:.4f}. This is the predeclared decision, not a paper-equivalence claim. The exact .65/.02 criteria and both rejected budgets/scores remain visible. Calibration results below do not alter this selection. The reduced configuration is named EfficientAD-S reduced-budget variant.")
    md('### Reserved-normal calibration feasibility\n\nAfter the selection lock, use all reserved clean calibration normals: 31 bottle and 42 carpet. Freeze nominal 5% FPR, higher 95th percentile, strict score>threshold. Bootstrap 1,000 times and delete one sample at a time to expose threshold sensitivity. Also report the continuous-IID order-statistic future-FPR interval. A binomial interval on reused calibration exceedances is descriptive, not coverage for a fitted threshold.')
    code("calibration = [json.loads((D/f'calibration-{c}-corrected.json').read_text()) for c in plan['categories']]\nprint(json.dumps(calibration,indent=2))\nprint('Precision audit:',json.loads((D/'calibration-precision-audit.json').read_text()))\nfig, axes = plt.subplots(1,2,figsize=(10,3))\nfor ax,c in zip(axes,calibration):\n    table=pd.read_csv(D/f\"{c['category']}-calibration-exact-scores.csv\",float_precision='round_trip')\n    values=np.sort(table.score)\n    ax.step(values,np.arange(1,len(values)+1)/len(values),where='post')\n    ax.axvline(c['threshold'],color='red',label='fixed-policy threshold')\n    ax.set_title(c['category']+f\" n={len(values)}\"); ax.set_xlabel('Normal anomaly score'); ax.set_ylabel('ECDF'); ax.legend()\nfig.tight_layout(); plt.show()")
    md('The precision audit repairs an evaluation serialization error: rounded float32 decimal values read as float64 inflated bottle development exceedances. Original reports are preserved; exact values are now promoted before export and parsed with round-trip precision. No training, score definition, threshold or model selection changed. Bottle has one unique calibration score across 31 normals; its identical maximum is a score floor, while spatial maps still vary. The zero-width bootstrap range is not certainty; the continuous-score Beta interval is inapplicable and explicitly null. Carpet retains a wide bootstrap range. The smaller all-category calibration partitions (for example toothbrush n=9) will be still less precise. No calibration observations select a different setting or justify a post-test adjustment.')
    md('### Measured compute and 45-model feasibility\n\nUse complete-epoch timings from both categories, retaining the slower selected-budget seconds/image. Add measured full-fitting normalization/preparation, normal map scaling, calibration, decode-through-CPU-map inference, checkpoint serialization/reload, synthetic native-metric N log N cost, and 60 seconds/model fixed CPU artifact/validation overhead. Multiply the entire sequential elapsed estimate by two. Test counts and dimensions are metadata-only; no test pixels or masks were accessed.')
    code("print(pd.DataFrame([dict(category=r['category'],epochs=r['epochs'],train_s=r['training_seconds'],seconds_per_image_epoch=r['seconds_per_image_epoch'],prep_s=r['preparation_seconds'],diagnostics_s=r['diagnostic_seconds'],serialization_validation_s=r['serialization_validation_seconds'],ram_bytes=r['process_peak_working_set_bytes'],gpu_allocated_bytes=r['peak_gpu_allocated_bytes'],gpu_reserved_bytes=r['peak_gpu_reserved_bytes']) for r in results]).to_string(index=False))\nprint(json.dumps({k:v for k,v in gate.items() if k!='workload'},indent=2))\nprint(pd.DataFrame([dict(category=r['category'],**r['per_model_seconds'],three_seed_conservative_hours=r['conservative_three_seed_seconds']/3600) for r in gate['workload']]).to_string(index=False))")
    md(f"The conservative estimate is **{gate['estimated_conservative_total_elapsed_hours']:.2f} hours for 45 models**, including CPU work and a factor-two margin; raw projected training is {gate['estimated_training_hours_no_margin']:.2f} hours. Recommendation: **{gate['recommendation']}** against the 12-hour target. This is a cost forecast, not measured final GPU-hours; sustained thermals, other categories and exact native metric workloads may differ. All 15 categories and seeds 2026/2027/2028 remain planned. No final model has been trained by this phase.")
    md('### Development conclusion and remaining milestone work\n\nFour fits and their complete learning histories, latency audit, fidelity audit, calibration sensitivity and feasibility arithmetic are retained. Teacher provenance and separate checkpoint-license uncertainty remain unchanged. Missing penalty, short training, one development seed, optimistic proxies and small calibration tails limit the evidence. Final nine metrics, real category-specific failures and six-model comparison remain unavailable until a frozen benchmark. Notebook 07 remains unstarted. Validation and recovery evidence live in docs/milestone_status.md and reports/efficientad/development/validation.json.')
    # Execute only new replay cells; preserve all initial pilot outputs and execution counts.
    replay=n.v4.new_notebook(cells=cells,metadata=nb.metadata)
    os.environ['IPYTHONDIR']=str(ROOT/'.cache/ipython-efficientad')
    os.environ['JUPYTER_RUNTIME_DIR']=str(ROOT/'.cache/jupyter-efficientad')
    NotebookClient(replay,timeout=240,kernel_name='mvtec-research',resources={'metadata':{'path':str(ROOT)}}).execute()
    nb.cells.extend(replay.cells)
    nb.metadata['efficientad_development_replay']=dict(study_id='06-development-v1',fits=4,final_models=0)
    nb.cells.insert(1,n.v4.new_markdown_cell('**Continuation:** the original pilot record is preserved below. The executed bounded-development study follows section 20 and supersedes historical pending-development statements. Final benchmark and Notebook 07 have not started.'))
    n.write(nb,PATH)


if __name__=='__main__': main()
